def aspects(name):
    """'color', 'depth', 'stencil' or 'depth+stencil'."""
    c = {x[0] for x in FORMATS[name][5]}
    if 'D' in c or 'S' in c:
        return '+'.join(a for a, k in (('depth', 'D'), ('stencil', 'S'))
                        if k in c)
    return 'color'
